// gRPC IDL — .proto
service UserService {
  rpc GetUser (GetUserRequest) returns (GetUserResponse);
  rpc StreamUsers (StreamRequest) returns (stream User);  // server streaming
}
message GetUserRequest { int32 id = 1; }
message GetUserResponse { int32 id = 1; string name = 2; }

// Клиент (Python) — вызов выглядит как локальный:
response = stub.GetUser(user_pb2.GetUserRequest(id=42))
print(response.name)  # 'Alice'

// Под капотом:
// 1. stub.GetUser(42) — клиентский stub
// 2. marshal GetUserRequest{id:42} → bytes (Protobuf)
// 3. POST /UserService/GetUser HTTP/2, body=bytes
// 4. сервер: unmarshal → вызов GetUserHandler(req) → User{id:42,name:'Alice'}
// 5. marshal response → bytes → HTTP/2 response
// 6. клиент: unmarshal → GetUserResponse → return response
```
